package com.matt.quantumfalcon.client.gui;

import com.matt.quantumfalcon.QuantumFalcon;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.resources.ResourceLocation;

import java.util.List;

/** Generated by tools/bake_portraits.py: variant portraits baked into textures/gui/portraits.png (large 60x56, medium 36x24, small 18x14). */
public final class Portraits {
    public static final ResourceLocation SHEET = ResourceLocation.fromNamespaceAndPath(QuantumFalcon.MOD_ID, "textures/gui/portraits.png");
    public static final List<String> VARIANTS = List.of("peregrine", "prairie", "coral", "deepslate", "mushroom", "tempest", "tundra", "crimson", "soulfire", "stormrider", "abyssal", "aetherwing", "emberfrost", "sporewraith", "tidecaller", "voidstalker", "warped", "aurora_seraph", "chronowing", "entangled_prism", "rift_reaver", "cosmic", "nebula_prism", "singularity", "paradox", "quantum_phoenix");
    public static final int LARGE = 0, MEDIUM = 1, SMALL = 2;

    private Portraits() {}

    /** Draws the portrait centred in (x, y, w, h); returns false when the variant has no portrait. */
    public static boolean draw(GuiGraphics g, String variant, int size, int x, int y, int w, int h) {
        int i = VARIANTS.indexOf(variant);
        if (i < 0) return false;
        int pw = size == LARGE ? 60 : size == MEDIUM ? 36 : 18, ph = size == LARGE ? 56 : size == MEDIUM ? 24 : 14;
        int u = size == LARGE ? i % 8 * 60 : size == MEDIUM ? i % 14 * 36 : i % 28 * 18;
        int v = size == LARGE ? i / 8 * 56 : size == MEDIUM ? 224 + i / 14 * 24 : 272;
        g.blit(SHEET, x + (w - pw) / 2, y + (h - ph) / 2, u, v, pw, ph, 512, 512);
        return true;
    }
}
